#define ATTEST_PREFIX "storage/attest/"

static int safe_token(const char *s,size_t max){if(!s||!*s||strlen(s)>=max)return 0;for(const unsigned char*p=(const unsigned char*)s;*p;p++)if(*p=='|'||*p==';'||*p=='\n'||*p=='\r'||*p<32)return 0;return 1;}
static char *field(const char *payload,const char *key){if(!payload||!key)return NULL;size_t k=strlen(key);const char*p=payload;while(*p){while(*p==';')p++;const char*e=strchr(p,';');size_t n=e?(size_t)(e-p):strlen(p);if(n>k&&!memcmp(p,key,k)&&p[k]=='='){char*v=malloc(n-k);if(!v)return NULL;memcpy(v,p+k+1,n-k-1);v[n-k-1]=0;return v;}if(!e)break;p=e+1;}return NULL;}
static int parse_u64(const char*s,uint64_t*out){if(!s||!*s||!out)return -1;char*e=NULL;unsigned long long v=strtoull(s,&e,10);if(!e||*e)return -1;*out=(uint64_t)v;return 0;}
static int parse_u32(const char*s,uint32_t*out){uint64_t v=0;if(parse_u64(s,&v)||v>UINT32_MAX)return -1;*out=(uint32_t)v;return 0;}
static int hexv(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
static int unhex(const char*s,uint8_t*out,size_t n){if(!s||strlen(s)!=n*2)return -1;for(size_t i=0;i<n;i++){int a=hexv(s[i*2]),b=hexv(s[i*2+1]);if(a<0||b<0)return -1;out[i]=(uint8_t)((a<<4)|b);}return 0;}
static void hex64(const uint8_t in[64],char out[129]){static const char h[]="0123456789abcdef";for(int i=0;i<64;i++){out[i*2]=h[in[i]>>4];out[i*2+1]=h[in[i]&15];}out[128]=0;}
static int db_u64(QrxDB*db,const char*k,uint64_t def,uint64_t*out){char b[128];if(!db||!k||!out)return -1;if(qrxdb_get(db,k,b,sizeof(b))){*out=def;return 0;}return parse_u64(b,out);}
static int batch_u64(QrxDBBatch*b,const char*k,uint64_t v){char s[64];snprintf(s,sizeof(s),"%llu",(unsigned long long)v);return qrxdb_batch_put(b,k,s);}
static int pool_adjust(QrxDB*db,QrxDBBatch*b,const char*k,int64_t delta){uint64_t old=0;if(db_u64(db,k,0,&old))return -1;if(delta<0){uint64_t d=(uint64_t)(-delta);if(old<d)return -1;return batch_u64(b,k,old-d);}uint64_t d=(uint64_t)delta;if(UINT64_MAX-old<d)return -1;return batch_u64(b,k,old+d);}

static EVP_PKEY *provider_key_from_b64(const char *b64){
    if(!b64||!*b64)return NULL; size_t n=strlen(b64); if(n>16384)return NULL;
    unsigned char *buf=malloc(n+4); if(!buf)return NULL; int z=EVP_DecodeBlock(buf,(const unsigned char*)b64,(int)n);
    if(z<=0){free(buf);return NULL;} while(n&&b64[n-1]=='='){z--;n--;}
    BIO *bio=BIO_new_mem_buf(buf,z); EVP_PKEY *k=bio?PEM_read_bio_PUBKEY(bio,NULL,NULL,NULL):NULL; BIO_free(bio); free(buf); return k;
}
int qrx_storage_provider_discovery_key_lookup(void *ctx,const char *provider_id,EVP_PKEY **out){
    if(!ctx||!provider_id||!out||!safe_token(provider_id,129))return -1; *out=NULL; char key[320],b64[16384];
    snprintf(key,sizeof(key),"storage/provider-key/%s",provider_id); if(qrxdb_get((QrxDB*)ctx,key,b64,sizeof(b64)))return -1;
    EVP_PKEY *k=provider_key_from_b64(b64); if(!k)return -1; const char *name=EVP_PKEY_get0_type_name(k);
    if(!name||strcmp(name,"ML-DSA-65")){EVP_PKEY_free(k);return -1;} *out=k; return 0;
}

static int key_provider(const char*id,char out[300]){if(!safe_token(id,129))return -1;snprintf(out,300,PROVIDER_PREFIX"%s",id);return 0;}
static int key_contract(const char*id,char out[300]){if(!safe_token(id,129))return -1;snprintf(out,300,CONTRACT_PREFIX"%s",id);return 0;}
static int key_assign(const char*cid,uint32_t shard,char out[360]){if(!safe_token(cid,129))return -1;snprintf(out,360,ASSIGN_PREFIX"%s/%010u",cid,shard);return 0;}

static int provider_encode(const QrxStorageProviderState*p,char*out,size_t n){int z=snprintf(out,n,"1|%s|%u|%llu|%llu|%llu|%llu|%u|%u|%u|%u|%s|%s|%s|%s|%s|%llu",p->owner,p->status,(unsigned long long)p->bond_atoms,(unsigned long long)p->proven_capacity_bytes,(unsigned long long)p->allocated_bytes,(unsigned long long)p->exit_height,p->availability_bps,p->proof_success_bps,p->performance_bps,p->reputation_bps,p->operator_id[0]?p->operator_id:"-",p->claimed_asn[0]?p->claimed_asn:"-",p->claimed_region[0]?p->claimed_region:"-",p->attested_asn[0]?p->attested_asn:"-",p->attested_region[0]?p->attested_region:"-",(unsigned long long)p->attestation_epoch);return z>0&&(size_t)z<n?0:-1;}
static int provider_decode(const char*v,QrxStorageProviderState*p){if(!v||!p)return -1;char*t=strdup(v);if(!t)return -1;char*s=NULL,*a[17];int n=0;for(char*x=strtok_r(t,"|",&s);x&&n<17;x=strtok_r(NULL,"|",&s))a[n++]=x;if(n!=17||strcmp(a[0],"1")){free(t);return -1;}memset(p,0,sizeof(*p));if(!safe_token(a[1],160)||strlen(a[11])>=129||strlen(a[12])>=64||strlen(a[13])>=96||strlen(a[14])>=64||strlen(a[15])>=96){free(t);return -1;}strcpy(p->owner,a[1]);p->status=(uint32_t)strtoul(a[2],NULL,10);p->bond_atoms=strtoull(a[3],NULL,10);p->proven_capacity_bytes=strtoull(a[4],NULL,10);p->allocated_bytes=strtoull(a[5],NULL,10);p->exit_height=strtoull(a[6],NULL,10);p->availability_bps=(uint32_t)strtoul(a[7],NULL,10);p->proof_success_bps=(uint32_t)strtoul(a[8],NULL,10);p->performance_bps=(uint32_t)strtoul(a[9],NULL,10);p->reputation_bps=(uint32_t)strtoul(a[10],NULL,10);if(strcmp(a[11],"-"))strcpy(p->operator_id,a[11]);if(strcmp(a[12],"-"))strcpy(p->claimed_asn,a[12]);if(strcmp(a[13],"-"))strcpy(p->claimed_region,a[13]);if(strcmp(a[14],"-"))strcpy(p->attested_asn,a[14]);if(strcmp(a[15],"-"))strcpy(p->attested_region,a[15]);p->attestation_epoch=strtoull(a[16],NULL,10);free(t);return 0;}
int qrx_storage_provider_get(QrxDB*db,const char*id,QrxStorageProviderState*out){char k[300],v[1400];if(!db||!out||key_provider(id,k)||qrxdb_get(db,k,v,sizeof(v)))return -1;return provider_decode(v,out);}
static int provider_put(QrxDBBatch*b,const char*id,const QrxStorageProviderState*p){char k[300],v[1400];if(key_provider(id,k)||provider_encode(p,v,sizeof(v)))return -1;return qrxdb_batch_put(b,k,v);}

static int contract_encode(const QrxStorageContractState*c,char*out,size_t n){char mh[129];hex64(c->manifest_root,mh);int z=snprintf(out,n,"1|%s|%s|%llu|%llu|%u|%llu|%llu|%llu|%llu|%llu|%llu|%llu|%llu|%llu|%llu|%s|%u",c->owner,c->profile,(unsigned long long)c->logical_bytes,(unsigned long long)c->shard_bytes,c->shard_count,(unsigned long long)c->start_height,(unsigned long long)c->end_height,(unsigned long long)c->original_atoms,(unsigned long long)c->development_atoms,(unsigned long long)c->resilience_atoms,(unsigned long long)c->provider_escrow_atoms,(unsigned long long)c->provider_paid_atoms,(unsigned long long)c->repair_paid_atoms,(unsigned long long)c->egress_paid_atoms,(unsigned long long)c->base_atoms_per_gib_epoch,mh,c->status);return z>0&&(size_t)z<n?0:-1;}
static int contract_decode(const char*v,QrxStorageContractState*c){if(!v||!c)return -1;char*t=strdup(v);if(!t)return -1;char*s=NULL,*a[18];int n=0;for(char*x=strtok_r(t,"|",&s);x&&n<18;x=strtok_r(NULL,"|",&s))a[n++]=x;if(n!=18||strcmp(a[0],"1")||!safe_token(a[1],160)||strlen(a[2])>=16){free(t);return -1;}memset(c,0,sizeof(*c));strcpy(c->owner,a[1]);strcpy(c->profile,a[2]);c->logical_bytes=strtoull(a[3],NULL,10);c->shard_bytes=strtoull(a[4],NULL,10);c->shard_count=(uint32_t)strtoul(a[5],NULL,10);c->start_height=strtoull(a[6],NULL,10);c->end_height=strtoull(a[7],NULL,10);c->original_atoms=strtoull(a[8],NULL,10);c->development_atoms=strtoull(a[9],NULL,10);c->resilience_atoms=strtoull(a[10],NULL,10);c->provider_escrow_atoms=strtoull(a[11],NULL,10);c->provider_paid_atoms=strtoull(a[12],NULL,10);c->repair_paid_atoms=strtoull(a[13],NULL,10);c->egress_paid_atoms=strtoull(a[14],NULL,10);c->base_atoms_per_gib_epoch=strtoull(a[15],NULL,10);if(unhex(a[16],c->manifest_root,64)){free(t);return -1;}c->status=(QrxStorageContractStatus)strtoul(a[17],NULL,10);free(t);return 0;}
int qrx_storage_contract_get(QrxDB*db,const char*id,QrxStorageContractState*out){char k[300],v[1800];if(!db||!out||key_contract(id,k)||qrxdb_get(db,k,v,sizeof(v)))return -1;return contract_decode(v,out);}
static int contract_put(QrxDBBatch*b,const char*id,const QrxStorageContractState*c){char k[300],v[1800];if(key_contract(id,k)||contract_encode(c,v,sizeof(v)))return -1;return qrxdb_batch_put(b,k,v);}

static int assign_encode(const QrxStorageAssignmentRecord*a,char*out,size_t n){char rh[129];hex64(a->merkle_root,rh);int z=snprintf(out,n,"1|%s|%u|%llu|%s|%s|%llu|%llu|%llu|%llu|%llu",a->provider_id,a->state,(unsigned long long)a->physical_bytes,a->object_id,rh,(unsigned long long)a->leaf_count,(unsigned long long)a->accepted_height,(unsigned long long)a->last_proof_epoch,(unsigned long long)a->last_proof_height,(unsigned long long)a->last_settled_epoch);return z>0&&(size_t)z<n?0:-1;}
static int assign_decode(const char*v,QrxStorageAssignmentRecord*a){if(!v||!a)return -1;char*t=strdup(v);if(!t)return -1;char*s=NULL,*p[11];int n=0;for(char*x=strtok_r(t,"|",&s);x&&n<11;x=strtok_r(NULL,"|",&s))p[n++]=x;if(n!=11||strcmp(p[0],"1")||strlen(p[1])>=129||strlen(p[4])!=64){free(t);return -1;}memset(a,0,sizeof(*a));strcpy(a->provider_id,p[1]);a->state=(uint32_t)strtoul(p[2],NULL,10);a->physical_bytes=strtoull(p[3],NULL,10);strcpy(a->object_id,p[4]);if(unhex(p[5],a->merkle_root,64)){free(t);return -1;}a->leaf_count=strtoull(p[6],NULL,10);a->accepted_height=strtoull(p[7],NULL,10);a->last_proof_epoch=strtoull(p[8],NULL,10);a->last_proof_height=strtoull(p[9],NULL,10);a->last_settled_epoch=strtoull(p[10],NULL,10);free(t);return 0;}
int qrx_storage_assignment_get(QrxDB*db,const char*cid,uint32_t shard,QrxStorageAssignmentRecord*out){char k[360],v[1200];if(!db||!out||key_assign(cid,shard,k)||qrxdb_get(db,k,v,sizeof(v)))return -1;return assign_decode(v,out);}
int qrx_storage_repair_get(QrxDB*db,const char*cid,uint32_t shard,QrxStorageRepairRecord*out){
    if(!db||!cid||!out||!safe_token(cid,129))return -1;char k[400],v[900];snprintf(k,sizeof(k),REPAIR_PREFIX"%s/%010u",cid,shard);if(qrxdb_get(db,k,v,sizeof(v)))return -1;
    char*t=strdup(v),*sv=NULL,*a[10];int n=0;if(!t)return -1;for(char*x=strtok_r(t,"|",&sv);x&&n<10;x=strtok_r(NULL,"|",&sv))a[n++]=x;
    if(n!=10||strcmp(a[0],"1")||strlen(a[1])>=129||strlen(a[2])>=129||strlen(a[6])!=64||strlen(a[7])!=128){free(t);return -1;}
    memset(out,0,sizeof(*out));snprintf(out->old_provider_id,sizeof(out->old_provider_id),"%s",a[1]);snprintf(out->replacement_provider_id,sizeof(out->replacement_provider_id),"%s",a[2]);out->state=(uint32_t)strtoul(a[3],NULL,10);out->start_height=strtoull(a[4],NULL,10);out->physical_bytes=strtoull(a[5],NULL,10);snprintf(out->object_id,sizeof(out->object_id),"%s",a[6]);if(unhex(a[7],out->merkle_root,64)){free(t);return -1;}out->leaf_count=strtoull(a[8],NULL,10);out->accepted_height=strtoull(a[9],NULL,10);free(t);return 0;
}
static int assign_put(QrxDBBatch*b,const char*cid,uint32_t shard,const QrxStorageAssignmentRecord*a){char k[360],v[1200];if(key_assign(cid,shard,k)||assign_encode(a,v,sizeof(v)))return -1;return qrxdb_batch_put(b,k,v);}

static int block_hash_at(QrxDB*db,uint64_t h,uint8_t out[64]){char x[160];if(qrxdb_chain_get_block_hash_by_height(db,h,x,sizeof(x)))return -1;return unhex(x,out,64);}
static int parse_merkle_proof(const char*siblings,uint64_t leaf_index,uint64_t leaf_count,QrxMerkleProof*out){if(!out||!leaf_count)return -1;memset(out,0,sizeof(*out));out->leaf_index=leaf_index;out->leaf_count=leaf_count;if(!siblings||!*siblings||!strcmp(siblings,"-")){out->depth=0;return leaf_count==1?0:-1;}size_t n=strlen(siblings);if(n%128)return -1;size_t d=n/128;if(d>QRX_MERKLE_MAX_DEPTH)return -1;out->depth=(uint32_t)d;for(size_t i=0;i<d;i++){char x[129];memcpy(x,siblings+i*128,128);x[128]=0;if(unhex(x,out->siblings[i],64))return -1;}return 0;}

typedef struct {QrxStoragePlacementCandidate *v;size_t n,cap;QrxDB*db;} CandCtx;
static int candidate_cb(const char*k,const char*v,uint32_t vl,void*ctxp){(void)vl;CandCtx*c=ctxp;QrxStorageProviderState p;if(strncmp(k,PROVIDER_PREFIX,strlen(PROVIDER_PREFIX))||provider_decode(v,&p))return 0;if(p.status!=QRX_PROVIDER_ACTIVE||p.proven_capacity_bytes<=p.allocated_bytes)return 0;if(c->n==c->cap){size_t nc=c->cap?c->cap*2:16;void*np=realloc(c->v,nc*sizeof(*c->v));if(!np)return -1;c->v=np;c->cap=nc;}QrxStoragePlacementCandidate*x=&c->v[c->n++];memset(x,0,sizeof(*x));snprintf(x->provider_id,sizeof(x->provider_id),"%s",k+strlen(PROVIDER_PREFIX));snprintf(x->operator_id,sizeof(x->operator_id),"%.96s",p.operator_id[0]?p.operator_id:x->provider_id);snprintf(x->asn,sizeof(x->asn),"%s",p.attested_asn[0]?p.attested_asn:p.claimed_asn);snprintf(x->region,sizeof(x->region),"%s",p.attested_region[0]?p.attested_region:p.claimed_region);x->failure_domain_attested=p.attested_asn[0]&&p.attested_region[0];x->proven_free_bytes=p.proven_capacity_bytes-p.allocated_bytes;x->bond_atoms=p.bond_atoms;x->availability_bps=p.availability_bps;x->proof_success_bps=p.proof_success_bps;x->performance_bps=p.performance_bps;x->price_atoms_per_gib_epoch=1;x->active=1;return 0;}
typedef struct{const char*cid;char **providers,**operators,**asns,**regions;size_t n,cap;QrxDB*db;} ExCtx;
static int exclusions_cb(const char*k,const char*v,uint32_t vl,void*ctxp){(void)k;(void)vl;ExCtx*c=ctxp;QrxStorageAssignmentRecord a;if(assign_decode(v,&a)||a.state==QRX_ASSIGN_REPLACED)return 0;if(c->n==c->cap){size_t nc=c->cap?c->cap*2:16;char**p=realloc(c->providers,nc*sizeof(char*));char**o=realloc(c->operators,nc*sizeof(char*));char**as=realloc(c->asns,nc*sizeof(char*));char**r=realloc(c->regions,nc*sizeof(char*));if(!p||!o||!as||!r){free(p);free(o);free(as);free(r);return -1;}c->providers=p;c->operators=o;c->asns=as;c->regions=r;c->cap=nc;}c->providers[c->n]=strdup(a.provider_id);QrxStorageProviderState ps;if(qrx_storage_provider_get(c->db,a.provider_id,&ps)==0){c->operators[c->n]=strdup(ps.operator_id[0]?ps.operator_id:a.provider_id);c->asns[c->n]=strdup(ps.attested_asn);c->regions[c->n]=strdup(ps.attested_region);}else{c->operators[c->n]=strdup(a.provider_id);c->asns[c->n]=strdup("");c->regions[c->n]=strdup("");}if(!c->providers[c->n]||!c->operators[c->n]||!c->asns[c->n]||!c->regions[c->n])return -1;c->n++;return 0;}
static void exclusions_free(ExCtx*c){if(!c)return;for(size_t i=0;i<c->n;i++){free(c->providers[i]);free(c->operators[i]);free(c->asns[i]);free(c->regions[i]);}free(c->providers);free(c->operators);free(c->asns);free(c->regions);memset(c,0,sizeof(*c));}
static int deterministic_provider_seed(QrxDB*db,const char*cid,uint64_t bytes,uint64_t seed_height,char out[129]){CandCtx cc={0};cc.db=db;if(qrxdb_scan_prefix(db,PROVIDER_PREFIX,candidate_cb,&cc)||!cc.n){free(cc.v);return -1;}char pre[360];snprintf(pre,sizeof(pre),ASSIGN_PREFIX"%s/",cid);ExCtx ex={0};ex.cid=cid;ex.db=db;if(qrxdb_scan_prefix(db,pre,exclusions_cb,&ex)){free(cc.v);exclusions_free(&ex);return -1;}const char **pp=(const char**)ex.providers,**oo=(const char**)ex.operators,**aa=(const char**)ex.asns,**rr=(const char**)ex.regions;QrxStoragePlacementExclusions x={pp,ex.n,oo,ex.n,aa,ex.n,rr,ex.n};uint8_t rnd[64];if(block_hash_at(db,seed_height,rnd)){free(cc.v);exclusions_free(&ex);return -1;}size_t idx=0;int rc=qrx_storage_select_provider(cc.v,cc.n,&x,bytes,1,rnd,&idx);if(!rc)snprintf(out,129,"%s",cc.v[idx].provider_id);free(cc.v);exclusions_free(&ex);return rc;}

static int capacity_get(QrxDB*db,const char*pid,QrxCapacityCommitment*c,uint64_t*commit_h,int*verified){char k[300],v[1000];snprintf(k,sizeof(k),CAPACITY_PREFIX"%s",pid);if(qrxdb_get(db,k,v,sizeof(v)))return -1;char*t=strdup(v),*s=NULL,*a[8];int n=0;for(char*x=strtok_r(t,"|",&s);x&&n<8;x=strtok_r(NULL,"|",&s))a[n++]=x;if(n!=8||strcmp(a[0],"1")){free(t);return -1;}memset(c,0,sizeof(*c));c->version=1;snprintf(c->provider_id,sizeof(c->provider_id),"%s",pid);c->epoch=strtoull(a[1],NULL,10);c->slot_count=strtoull(a[2],NULL,10);c->slot_bytes=(uint32_t)strtoul(a[3],NULL,10);if(unhex(a[4],c->merkle_root,64)){free(t);return -1;}if(commit_h)*commit_h=strtoull(a[5],NULL,10);if(verified)*verified=atoi(a[6]);free(t);return 0;}
static int capacity_put(QrxDBBatch*b,const QrxCapacityCommitment*c,uint64_t h,int verified){char k[300],v[1000],rh[129];hex64(c->merkle_root,rh);snprintf(k,sizeof(k),CAPACITY_PREFIX"%s",c->provider_id);snprintf(v,sizeof(v),"1|%llu|%llu|%u|%s|%llu|%d|-",(unsigned long long)c->epoch,(unsigned long long)c->slot_count,c->slot_bytes,rh,(unsigned long long)h,verified);return qrxdb_batch_put(b,k,v);}

static int contract_shard_layout(const char*profile,uint64_t logical,uint64_t*shard_bytes,uint32_t*count){const QrxStorageRedundancyProfile*p=qrx_storage_profile_by_name(profile);if(!p||!logical||!shard_bytes||!count)return -1;if(p->full_replicas){*shard_bytes=logical;*count=p->full_replicas;return 0;}if(!p->data_shards||p->data_shards+p->parity_shards>UINT32_MAX)return -1;*shard_bytes=(logical+p->data_shards-1)/p->data_shards;*count=p->data_shards+p->parity_shards;return 0;}

