static int stage_attestation(QrxDB*db,QrxDBBatch*b,const char*from,const char*p,uint64_t h){char*target=field(p,"target_provider"),*asn=field(p,"asn"),*region=field(p,"region"),*ep=field(p,"epoch");uint64_t epoch=0;if(!target||!asn||!region||parse_u64(ep,&epoch)){free(target);free(asn);free(region);free(ep);return -1;}char k[600],v[300];snprintf(k,sizeof(k),ATTEST_PREFIX"%s/%020llu/%s",target,(unsigned long long)epoch,from);snprintf(v,sizeof(v),"1|%s|%s|%llu",asn,region,(unsigned long long)h);if(qrxdb_batch_put(b,k,v)){free(target);free(asn);free(region);free(ep);return -1;}AttestCountCtx c={asn,region,1};char pre[500];snprintf(pre,sizeof(pre),ATTEST_PREFIX"%s/%020llu/",target,(unsigned long long)epoch);qrxdb_scan_prefix(db,pre,attest_count_cb,&c);if(c.matches>=QRX_STORAGE_ATTEST_QUORUM){QrxStorageProviderState ps;if(qrx_storage_provider_get(db,target,&ps)==0){snprintf(ps.attested_asn,sizeof(ps.attested_asn),"%s",asn);snprintf(ps.attested_region,sizeof(ps.attested_region),"%s",region);ps.attestation_epoch=epoch;if(provider_put(b,target,&ps)){free(target);free(asn);free(region);free(ep);return -1;}}}free(target);free(asn);free(region);free(ep);return 0;}

