    if(!strcmp(tx,"STORAGE_REPAIR_START")){char*cid=field(p,"contract_id"),*sh=field(p,"shard_index");uint32_t shard=0;parse_u32(sh,&shard);QrxStorageAssignmentRecord a;qrx_storage_assignment_get(db,cid,shard,&a);char replacement[129];if(deterministic_provider_seed(db,cid,a.physical_bytes,h?h-1:0,replacement)){free(cid);free(sh);return -1;}QrxStorageProviderState oldp,newp;if(qrx_storage_provider_get(db,a.provider_id,&oldp)||qrx_storage_provider_get(db,replacement,&newp)){free(cid);free(sh);return -1;}if(oldp.allocated_bytes<a.physical_bytes||UINT64_MAX-newp.allocated_bytes<a.physical_bytes){free(cid);free(sh);return -1;}oldp.allocated_bytes-=a.physical_bytes;newp.allocated_bytes+=a.physical_bytes;a.state=QRX_ASSIGN_REPAIRING;char rh[129],rk[400],rv[900];hex64(a.merkle_root,rh);snprintf(rk,sizeof(rk),REPAIR_PREFIX"%s/%010u",cid,shard);snprintf(rv,sizeof(rv),"1|%s|%s|%u|%llu|%llu|%s|%s|%llu|0",a.provider_id,replacement,QRX_ASSIGN_REPAIRING,(unsigned long long)h,(unsigned long long)a.physical_bytes,a.object_id,rh,(unsigned long long)a.leaf_count);int rc=assign_put(b,cid,shard,&a)||provider_put(b,a.provider_id,&oldp)||provider_put(b,replacement,&newp)||qrxdb_batch_put(b,rk,rv);free(cid);free(sh);return rc;}
    if(!strcmp(tx,"STORAGE_REPAIR_ACCEPT")){char*cid=field(p,"contract_id"),*sh=field(p,"shard_index");uint32_t shard=0;parse_u32(sh,&shard);char rk[400],rv[900];snprintf(rk,sizeof(rk),REPAIR_PREFIX"%s/%010u",cid,shard);if(qrxdb_get(db,rk,rv,sizeof(rv))){free(cid);free(sh);return -1;}char*t=strdup(rv),*sv=NULL,*a[10];int n=0;for(char*x=strtok_r(t,"|",&sv);x&&n<10;x=strtok_r(NULL,"|",&sv))a[n++]=x;if(n!=10){free(t);free(cid);free(sh);return -1;}char nv[900];snprintf(nv,sizeof(nv),"1|%s|%s|%u|%s|%s|%s|%s|%s|%llu",a[1],a[2],QRX_ASSIGN_ACTIVE,a[4],a[5],a[6],a[7],a[8],(unsigned long long)h);int rc=qrxdb_batch_put(b,rk,nv);free(t);free(cid);free(sh);return rc;}
